def gen(rng):
    def build(n, kind):
        # returns list of (p, c) with node labels permuted, root fixed as 0
        perm = list(range(1, n))
        rng.shuffle(perm)
        labels = [0] + perm
        edges = []
        for i in range(1, n):
            if kind == 'path':
                p = i - 1
            elif kind == 'star':
                p = 0
            elif kind == 'wide':
                p = rng.randint(0, min(i - 1, 5))
            elif kind == 'deep':
                p = rng.randint(max(0, i - 3), i - 1)
            elif kind == 'broom':
                p = i - 1 if i < 4000 else rng.randint(3000, 3999)
            else:
                p = rng.randint(0, i - 1)
            edges.append((labels[p], labels[i]))
        rng.shuffle(edges)
        return edges
    def fmt(n, x, edges):
        return f'{n} {x}\n' + '\n'.join(f'{p} {c}' for p, c in edges) if edges else f'{n} {x}'
    tests = ['8 4\n0 1\n0 2\n0 3\n1 4\n1 5\n2 6\n3 7', '5 1\n0 1\n0 2\n2 3\n2 4', '7 6\n0 1\n1 2\n1 3\n3 4\n2 5\n2 6', '1 0', '2 1\n0 1', '3 0\n0 1\n0 2']
    for n in (3, 4, 5, 6, 8, 10, 14, 20, 25):
        for kind in ('random', 'wide', 'deep', 'random'):
            edges = build(n, kind)
            tests.append(fmt(n, rng.randrange(n), edges))
    n = 100000
    for kind in ('random', 'wide', 'star', 'broom'):
        edges = build(n, kind)
        tests.append(fmt(n, rng.randrange(n), edges))
    for kind in ('path', 'deep'):
        edges = build(5000, kind)
        tests.append(fmt(5000, rng.randrange(5000), edges))
    return tests

